/* eslint-disable max-len, no-restricted-syntax, no-invalid-this */

'use strict';

// MODULES //

var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var inherits = require( '@stdlib/utils/inherit' );
var stride2offset = require( '@stdlib/strided/base/stride2offset' );
var Memory = require( '@stdlib/wasm/memory' );
var arrays2ptrs = require( '@stdlib/wasm/base/arrays2ptrs' );
var strided2object = require( '@stdlib/wasm/base/strided2object' );
var Module = require( './module.js' );


// MAIN //

/**
* Routine constructor.
*
* @private
* @constructor
* @returns {Routine} routine instance
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Uint8Array = require( '@stdlib/array/uint8' );
*
* // Create a new routine:
* var dmskmaxabs = new Routine();
*
* // Initialize the module:
* dmskmaxabs.initializeSync();
*
* // Define strided arrays:
* var x = new Float64Array( [ 1.0, -2.0, 4.0, 2.0 ] );
* var mask = new Uint8Array( [ 0, 0, 1, 0 ] );
*
* // Perform operation:
* var v = dmskmaxabs.main( x.length, x, 1, mask, 1 );
* // returns 2.0
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Uint8Array = require( '@stdlib/array/uint8' );
*
* // Create a new routine:
* var dmskmaxabs = new Routine();
*
* // Initialize the module:
* dmskmaxabs.initializeSync();
*
* // Define strided arrays:
* var x = new Float64Array( [ 1.0, -2.0, 4.0, 2.0 ] );
* var mask = new Uint8Array( [ 0, 0, 1, 0 ] );
*
* // Perform operation:
* var v = dmskmaxabs.ndarray( x.length, x, 1, 0, mask, 1, 0 );
* // returns 2.0
*/
function Routine() {
	if ( !( this instanceof Routine ) ) {
		return new Routine();
	}
	Module.call( this, new Memory({
		'initial': 0
	}));
	return this;
}

// Inherit from the parent constructor:
inherits( Routine, Module );

/**
* Computes the maximum absolute value of a double-precision floating-point strided array according to a mask.
*
* @name main
* @memberof Routine.prototype
* @readonly
* @type {Function}
* @param {PositiveInteger} N - number of indexed elements
* @param {Float64Array} x - input array
* @param {integer} strideX - `x` stride length
* @param {Uint8Array} mask - mask array
* @param {integer} strideMask - `mask` stride length
* @returns {number} maximum absolute value
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Uint8Array = require( '@stdlib/array/uint8' );
*
* // Create a new routine:
* var dmskmaxabs = new Routine();
*
* // Initialize the module:
* dmskmaxabs.initializeSync();
*
* // Define strided arrays:
* var x = new Float64Array( [ 1.0, -2.0, 4.0, 2.0 ] );
* var mask = new Uint8Array( [ 0, 0, 1, 0 ] );
*
* // Perform operation:
* var v = dmskmaxabs.main( x.length, x, 1, mask, 1 );
* // returns 2.0
*/
setReadOnly( Routine.prototype, 'main', function dmskmaxabs( N, x, strideX, mask, strideMask ) {
	return this.ndarray( N, x, strideX, stride2offset( N, strideX ), mask, strideMask, stride2offset( N, strideMask ) );
});

/**
* Computes the maximum absolute value of a double-precision floating-point strided array according to a mask using alternative indexing semantics.
*
* @name ndarray
* @memberof Routine.prototype
* @readonly
* @type {Function}
* @param {PositiveInteger} N - number of indexed elements
* @param {Float64Array} x - input array
* @param {integer} strideX - `x` stride length
* @param {NonNegativeInteger} offsetX - starting `x` index
* @param {Uint8Array} mask - mask array
* @param {integer} strideMask - `mask` stride length
* @param {NonNegativeInteger} offsetMask - starting `mask` index
* @returns {number} maximum absolute value
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Uint8Array = require( '@stdlib/array/uint8' );
*
* // Create a new routine:
* var dmskmaxabs = new Routine();
*
* // Initialize the module:
* dmskmaxabs.initializeSync();
*
* // Define strided arrays:
* var x = new Float64Array( [ 1.0, -2.0, 4.0, 2.0 ] );
* var mask = new Uint8Array( [ 0, 0, 1, 0 ] );
*
* // Perform operation:
* var v = dmskmaxabs.ndarray( x.length, x, 1, 0, mask, 1, 0 );
* // returns 2.0
*/
setReadOnly( Routine.prototype, 'ndarray', function dmskmaxabs( N, x, strideX, offsetX, mask, strideMask, offsetMask ) {
	var ptrs;
	var p0;
	var p1;

	// Convert the input arrays to "pointers" in the module's memory:
	ptrs = arrays2ptrs( this, [
		strided2object( N, x, strideX, offsetX ),
		strided2object( N, mask, strideMask, offsetMask )
	]);
	p0 = ptrs[ 0 ];
	p1 = ptrs[ 1 ];

	// Perform computation by calling the corresponding parent method:
	return Module.prototype.ndarray.call( this, N, p0.ptr, p0.stride, p0.offset, p1.ptr, p1.stride, p1.offset );
});


// EXPORTS //

module.exports = Routine;
